    assert.strictEqual(detection.spatialResult.spatialSource, SpatialCalculationSource.RASTER);
    assert.ok(detection.changeIndicators.vvDelta !== undefined);
    assert.ok(detection.changeIndicators.vhDelta !== undefined);
